// ==========================================

let data;

// Webhook data can arrive through:
// - body
// - query
// - data
// - direct input

if (
  input.body &&
  typeof input.body === "object" &&
  !Array.isArray(input.body) &&
  Object.keys(input.body).length > 0
) {
  data = input.body;
}

else if (
  input.query &&
  typeof input.query === "object" &&
  !Array.isArray(input.query) &&
  Object.keys(input.query).length > 0
) {
  data = input.query;
}

else if (
  input.data &&
  typeof input.data === "object" &&
  !Array.isArray(input.data) &&
  Object.keys(input.data).length > 0
) {
  data = input.data;
}

else {
  data = input;
}


// ==========================================
// HANDLE JSON STRING
// ==========================================

if (typeof data === "string") {
  try {
    data = JSON.parse(data);
  } catch (error) {
    data = {};
  }
}


// ==========================================
// HANDLE NESTED DATA OBJECT
// ==========================================

if (
  data &&
  typeof data.data === "object" &&
  !Array.isArray(data.data)
) {
  data = {
    ...data,
    ...data.data
  };
}


// ==========================================
// HELPER FUNCTIONS
// ==========================================

function getValue(...values) {

  for (const value of values) {

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ""
    ) {
      return String(value).trim();
    }

  }

  return "";
}


function escapeHtml(value) {

  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");

}


