  data.name,
  data.fullName,
  data.full_name,
  data.fullname,

  data["full-name"],
  data["Full Name"],
  data["full name"],

  data.applicantName,
  data.applicant_name,

  data.contactName,
  data.contact_name

) || "Unknown";


